// 1. External Linkage (Strong Symbols)
// Definition must reside in exactly one translation unit (TU).

// TU 1: Definition
int shared_variable = 42;
void external_func(int a) { /* ... */ }

// TU 2: Declaration/Reference
extern int shared_variable;
extern void external_func(int);

void caller() {
    // Linker resolves symbol names to addresses
    external_func(shared_variable);
}


// 2. Internal Linkage (Symbol Hiding)
// 'static' prevents symbol resolution outside the TU.

// TU 1
static int local_only = 5;

void process() {
    // Linker does not export 'local_only'
    // or 'static_helper' for external use.
}


// 3. Weak Symbols (Handling Multiple Definitions)
// Often used for common definitions (e.g., templates/inline).
// Strong definitions override weak ones during linking.

__attribute__((weak))
void user_hook() { /* default implementation */ }

// In another TU: Strong definition overrides the weak one
void user_hook() {
    // Custom specialized implementation
}

// Reference point: Linker chooses the strong symbol.
void execute_hook() {
    user_hook();
}
